  str_n27_valentine_y_letter_writter_4 = "El Gobernante de Truenos y Relámpagos Silenciosos, Michael",
  str_n27_valentine_y_letter_writter_5 = "Tu aliado para siempre, Reinhardt",
  str_n27_valentine_y_letter_writter_6 = "tu amiga flor",
  str_n27_valentine_y_letter_writter_7 = "Tu indispensable amigo mayordomo, Minos",
  str_n27_valentine_y_letter_reply_1 = "Envió el chocolate de Jeriah.\n¿Le gustará?\nEspero que ella responda pronto.",
  str_n27_valentine_y_letter_reply_2 = "Envié el chocolate de Kya.\nMe pregunto dónde está ahora?\nCon suerte, ella lo recibe.",
  str_n27_valentine_y_letter_reply_3 = "Envió el chocolate de Gronru.\nVienen en una caja de trofeos.\nA ella le debería gustar eso, ¿verdad?",
  str_n27_valentine_y_letter_reply_4 = "Envié el chocolate de Michael.\nNunca la había visto comer antes.\n¿Le gustará esto?",
  str_n27_valentine_y_letter_reply_5 = "Envió el chocolate de Reinhardt.\n¿Le gustan los dulces?\nEspero que lo pruebe pronto.",
  str_n27_valentine_y_letter_reply_6 = "Envié el chocolate de Fleur.\nRecibe muchas cartas de amor;\nOjalá lo consiga.",
